import {MODULE_ID} from '../../framework/constants.js';

/**
 * Toll the Dead — the cantrip deals 1d8 necrotic on a failed save, but 1d12 if
 * the target is already missing any hit points (XGE / PHB'24, identical).
 *
 * On damageRollComplete this reads the targeted creature's current HP. If the
 * target is wounded (current HP below max) it rebuilds the damage roll with the
 * d8 dice swapped to d12 (preserving dice count and any modifiers) and rewrites
 * the chat card so the corrected total is ready to apply. If the target is at
 * full HP the d8 stays. Reading a target's HP is a plain replicated-data read
 * and the caster only rewrites their own damage card — no GM or socket needed.
 *
 * Degradation (never blocks the vanilla roll):
 *   - No target selected, or the target's HP is unreadable → the 1d8 roll is left
 *     as-is.
 *   - Auto-substitute setting off → the roll is left as-is.
 *   - Roll structure unparseable (no d8 dice found) → left untouched, no error.
 *
 * Per-item settings (Manage Automations on the spell):
 *   - autoSubstitute: rewrite the damage card to 1d12 automatically (default),
 *     or leave the roll untouched.
 */

/**
 * The first user-targeted token's actor, if any (acting client's targets).
 * @returns {Actor|null}
 */
function targetedActor() {
    const token = game.user?.targets?.first?.();
    return token?.actor ?? null;
}

/**
 * Whether an actor is missing any hit points. Returns null when HP is unknown
 * (no actor, or the hp fields are not readable numbers).
 * @param {Actor|null} actor
 * @returns {boolean|null}
 */
function isWounded(actor) {
    const hp = actor?.system?.attributes?.hp;
    const value = Number(hp?.value);
    const max = Number(hp?.max);
    if (!Number.isFinite(value) || !Number.isFinite(max) || max <= 0) return null;
    return value < max;
}

/**
 * Rebuild a damage roll with every d8 die term swapped to d12, preserving the
 * dice count and all other terms/modifiers. Returns null if the roll has no d8
 * to swap (nothing to do) or cannot be reconstructed.
 * @param {Roll} roll
 * @returns {Promise<Roll|null>}
 */
async function swapD8toD12(roll) {
    // Swap the denomination on each d8 die term (count and other terms untouched),
    // then rebuild from the corrected formula so results/totals evaluate cleanly and
    // the roll keeps its DamageRoll class + damage-type options.
    let swapped = false;
    const DieTerm = foundry.dice?.terms?.Die ?? Die;
    for (const term of roll.terms ?? []) {
        if (term instanceof DieTerm && Number(term.faces) === 8) {
            term.faces = 12;
            swapped = true;
        }
    }
    if (!swapped) return null;

    const DamageRoll = CONFIG.Dice?.DamageRoll ?? Roll;
    const rebuilt = new DamageRoll(roll.formula, roll.data ?? {}, {...roll.options});
    await rebuilt.evaluate();
    return rebuilt;
}

async function damage(context) {
    if (!context.damageRolls?.length) return;

    const target = targetedActor();
    const wounded = isWounded(target);

    // No target or unreadable HP → never block the roll; leave the d8 as-is.
    if (wounded === null) return;

    // Full HP → the d8 is correct, nothing to do.
    if (!wounded) return;

    // Wounded but auto-substitute is off → leave the roll untouched.
    if (context.settings?.autoSubstitute === false) return;

    // Wounded + auto → rebuild each d8 roll as a d12 and rewrite the card.
    const newRolls = [];
    let changed = false;
    for (const roll of context.damageRolls) {
        const swapped = await swapD8toD12(roll).catch(() => null);
        if (swapped) {
            newRolls.push(swapped);
            changed = true;
        } else {
            newRolls.push(roll);
        }
    }

    // No d8 found to swap (unexpected roll structure) → leave the card untouched.
    if (!changed) return;

    await context.setDamageRolls(newRolls);

    // Reflect the corrected dice in Dice So Nice, if present.
    if (game.dice3d) {
        for (const roll of newRolls) {
            await game.dice3d.showForRoll(roll, game.user, true).catch(() => {});
        }
    }
}

export const tollTheDead = {
    id: 'tollTheDead',
    name: 'Toll the Dead',
    description: 'When you roll Toll the Dead damage against a target that is missing hit points, the d8 damage dice are automatically swapped to d12 and the chat card is rewritten with the corrected total. If no target is selected or its HP is unknown, the vanilla 1d8 roll is kept. A per-item setting can turn the auto-substitution off.',
    version: '1.1.0',
    autogenerated: true,
    settings: [
        {
            key: 'autoSubstitute',
            name: 'Auto-substitute dice',
            hint: 'On: rewrite the damage card to 1d12 when the target is wounded. Off: leave the roll untouched.',
            type: 'checkbox',
            default: true
        }
    ],
    match: {
        itemNames: ['Toll the Dead']
    },
    events: [
        // Item-lifecycle: only the spell's own damage cards.
        {
            event: 'damageRollComplete',
            handler: damage,
            priority: 50,
            scopes: ['item']
        }
    ]
};
